import{_ as a,o as n,c as o,a2 as s}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"La Teoría de los Planos y la Clasificación","description":"","frontmatter":{},"headers":[],"relativePath":"es/80-位面理论与分类.md","filePath":"es/80-位面理论与分类.md","lastUpdated":1789183869000}'),i={name:"es/80-位面理论与分类.md"};function l(d,e,t,r,c,p){return n(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="la-teoria-de-los-planos-y-la-clasificacion" tabindex="-1">La Teoría de los Planos y la Clasificación <a class="header-anchor" href="#la-teoria-de-los-planos-y-la-clasificacion" aria-label="Permalink to &quot;La Teoría de los Planos y la Clasificación&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>80</td></tr><tr><td>Módulo</td><td>Interacción Transplanar y Reglas Temporales</td></tr><tr><td>Palabras clave</td><td>teoría de los planos, clasificación de los planos, barreras de leyes, coordenadas de planos, Universo Hengyuan</td></tr></tbody></table><h2 id="i-la-definicion-basica-de-los-planos" tabindex="-1">I. La Definición Básica de los Planos <a class="header-anchor" href="#i-la-definicion-basica-de-los-planos" aria-label="Permalink to &quot;I. La Definición Básica de los Planos&quot;">​</a></h2><p>Dentro del marco del Universo Original Wanling Hengmao (Universo Hengyuan), un &quot;plano&quot; designa una región de existencia delimitada por un conjunto de leyes relativamente estables, que posee una continuidad espacio-temporal independiente. Un plano no es simplemente &quot;otro mundo&quot;, sino una proyección concretizada de la red de leyes en diferentes intervalos de parámetros. Cada plano posee sus constantes físicas únicas, densidad de energía, velocidad de flujo del tiempo y nivel de actividad de la conciencia, y estos parámetros constituyen juntos la &quot;huella de leyes&quot; del plano.</p><p>La existencia de los planos se origina en la no uniformidad de la red de leyes del Universo Hengyuan. Durante el funcionamiento de las leyes de origen del universo, debido a las diferencias en la distribución de la energía, la perturbación de la conciencia y la evolución histórica, se formaron naturalmente innumerables regiones de leyes con parámetros variados. Estas regiones están separadas por &quot;barreras de leyes&quot;, cuya fuerza depende del grado de diferencia en los parámetros de leyes entre planos adyacentes — cuanto mayor es la diferencia, más gruesa es la barrera y más difícil es la travesía.</p><p>El mecanismo del Ancla ocupa una posición central en la teoría de los planos. Un Ancla es esencialmente un nodo estable de la red de leyes; no solo puede mantener la estabilidad de las leyes de su propio plano, sino también servir como referencia de anclaje para las conexiones transplanares. Todas las conductas interactivas como la travesía transplanar, la comunicación y la arqueología deben usar el Ancla como origen de coordenadas para el posicionamiento y la calibración.</p><h2 id="ii-el-sistema-de-clasificacion-de-los-planos" tabindex="-1">II. El Sistema de Clasificación de los Planos <a class="header-anchor" href="#ii-el-sistema-de-clasificacion-de-los-planos" aria-label="Permalink to &quot;II. El Sistema de Clasificación de los Planos&quot;">​</a></h2><p>Los planos del Universo Hengyuan se dividen, según los parámetros de leyes, los niveles de energía y el grado de desarrollo civilizacional, en las siguientes cinco grandes categorías:</p><table tabindex="0"><thead><tr><th>Categoría</th><th>Características de leyes</th><th>Densidad de energía</th><th>Forma civilizacional típica</th><th>Dificultad de travesía</th></tr></thead><tbody><tr><td>Plano de Dominio Material</td><td>Leyes físicas dominantes, energía latente</td><td>Baja</td><td>Civilización tecnológica, civilización de cultivo principiante</td><td>Baja</td></tr><tr><td>Plano de Energía Manifestada</td><td>Leyes energéticas semimanifiestas, sistemas de cultivo maduros</td><td>Media</td><td>Civilización de cultivo medio-alto, civilización mágica</td><td>Media</td></tr><tr><td>Plano de Dominio de la Conciencia</td><td>Leyes de la conciencia manifiestas, materia moldeable por la voluntad</td><td>Alta</td><td>Civilización de cuerpos espirituales, civilización de agregado de conciencia</td><td>Alta</td></tr><tr><td>Plano de Leyes Fragmentadas</td><td>Leyes inestables, numerosas fisuras de leyes</td><td>Extremadamente alta y caótica</td><td>Planos salvajes, planos de ruinas</td><td>Extremadamente alta</td></tr><tr><td>Plano Cercano al Origen</td><td>Cercano a las leyes de origen del universo, parámetros próximos a los límites</td><td>Aproximándose al origen</td><td>Civilización suprema, guardianes de planos</td><td>Límite teórico</td></tr></tbody></table><p>Además de las cinco grandes categorías mencionadas, también existen algunos tipos especiales de planos, incluyendo: los Planos Espejo (existencias paralelas altamente simétricas en parámetros de leyes con un cierto plano), los Planos Intermedios (regiones de transición situadas entre las barreras de leyes de dos planos principales), los Planos Inactivos (planos antiguos con actividad de leyes extremadamente baja, casi detenidos) y los Planos Nacientes (planos jóvenes recién formados en la red de leyes, con parámetros aún no estabilizados).</p><h2 id="iii-coordenadas-de-planos-y-principio-de-posicionamiento" tabindex="-1">III. Coordenadas de Planos y Principio de Posicionamiento <a class="header-anchor" href="#iii-coordenadas-de-planos-y-principio-de-posicionamiento" aria-label="Permalink to &quot;III. Coordenadas de Planos y Principio de Posicionamiento&quot;">​</a></h2><p>El prerrequisito de la interacción transplanar es un posicionamiento preciso de los planos. El Universo Hengyuan ha establecido un &quot;sistema de coordenadas de planos en cuatro dimensiones&quot; basado en el Ancla, donde cada plano queda determinado de manera única por cuatro parámetros:</p><ol><li><strong>Código de huella de leyes</strong>: identificador único generado por el hash de los parámetros de leyes centrales del plano, de 128 bits de longitud.</li><li><strong>Grado de asociación al Ancla</strong>: la fuerza de conexión entre el plano y la red de Anclas conocida, con un rango de 0 a 1.</li><li><strong>Relación de flujo temporal</strong>: la relación entre el flujo temporal del plano y el tiempo estándar del Universo Hengyuan, comúnmente de 0,1 a 10.</li><li><strong>Número de dimensiones espaciales</strong>: el número de dimensiones espaciales perceptibles del plano, generalmente de 3 a 11 dimensiones.</li></ol><p>Los métodos de obtención de coordenadas de planos incluyen: detección automática por la red del Ancla, rastreo de señales de comunicación transplanar, residuos de coordenadas en ruinas arqueológicas y registros manuales de los viajeros transplanares. Todas las coordenadas de planos confirmadas se ingresan en la &quot;Base Central de Coordenadas de Planos del Universo Hengyuan&quot;, mantenida de manera unificada por la Administración de Planos bajo la Asamblea Legislativa del Ancla.</p><h2 id="iv-interacciones-naturales-entre-los-planos" tabindex="-1">IV. Interacciones Naturales Entre los Planos <a class="header-anchor" href="#iv-interacciones-naturales-entre-los-planos" aria-label="Permalink to &quot;IV. Interacciones Naturales Entre los Planos&quot;">​</a></h2><p>Incluso sin travesía activa, existen fenómenos de interacción natural entre los planos. El más común es la &quot;filtración de leyes&quot; — debido a barreras localmente débiles entre planos adyacentes, una pequeña cantidad de parámetros de leyes se filtran mutuamente, provocando fenómenos anómalos locales. Por ejemplo, los &quot;eventos sobrenaturales&quot; que aparecen ocasionalmente en los planos de dominio material suelen deberse a la filtración de leyes de un plano de energía manifestada vecino.</p><p>Otra interacción natural es la &quot;resonancia de planos&quot;. Cuando los códigos de huella de leyes de dos planos presentan un alto grado de similitud, se produce entre ellos una resonancia de leyes periódica, manifestada en la aparición en ambos planos, durante períodos específicos, de eventos históricos similares, trayectorias civilizacionales similares e incluso destinos personales similares. La resonancia de planos es un importante objeto de estudio de la arqueología de planos; mediante el análisis de los patrones de resonancia se puede inferir el estado civilizacional de planos desconocidos.</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La teoría de los planos es la piedra angular teórica de todas las prácticas de interacción transplanar. Comprender con precisión la esencia, la clasificación y los principios de posicionamiento de los planos es el prerrequisito para formular las reglas de travesía, las normas éticas y los mecanismos de prevención y control. La exploración de planos del Universo Hengyuan sigue siempre el principio de &quot;cognición primero, interacción con cautela&quot;, garantizando que, al expandir las fronteras de la civilización, no se cause interferencia irreversible a la evolución autónoma de ningún plano.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>81-位面穿梭规则 (Las Reglas de Travesía Transplanar)</li><li>88-跨位面伦理准则 (Las Normas Éticas Transplanares)</li><li>28-跨位面锚点连接 (Las Conexiones Transplanares del Ancla)</li></ul>',21)])])}const g=a(i,[["render",l]]);export{m as __pageData,g as default};
